faq: [
  {
    id: 1,
    question: "How long does luxury car engine reconditioning usually take?",
    answer: "Most reconditioning jobs are completed within five to ten working days, depending on parts availability and what our inspection uncovers during strip-down. We confirm a realistic timeframe once diagnostics are finished."
  },
  {
    id: 2,
    question: "What are the early signs my Audi or Land Rover engine needs work?",
    answer: "Common warning signs include knocking or rattling noises, excessive exhaust smoke, reduced power, rising oil consumption and persistent dashboard warning lights. Addressing these early usually keeps repair costs lower."
  },
  {
    id: 3,
    question: "What's the actual difference between reconditioning and rebuilding an engine?",
    answer: "Reconditioning restores worn components through machining and selective replacement, while a rebuild typically involves a more extensive strip-down and broader parts replacement. We'll advise based on your engine's actual condition."
  },
  {
    id: 4,
    question: "Do you offer same-day diagnostics quotes near Stanford-le-Hope?",
    answer: "Yes, we provide same-day diagnostic assessments and quotations for most Range Rover, Land Rover, BMW and Audi engine issues, helping you decide quickly without unnecessary delay."
  },
  {
    id: 5,
    question: "Is reconditioning generally cheaper than replacing the whole engine?",
    answer: "In most cases, yes. Reconditioning restores your existing engine to reliable condition for considerably less than a full replacement unit, provided the core block remains structurally sound."
  },
  {
    id: 6,
    question: "Will you work on cars from Corringham or Horndon-on-the-Hill?",
    answer: "Absolutely. Alongside Stanford-le-Hope itself, we regularly serve customers from Corringham, Horndon-on-the-Hill, Grays and across the wider Thurrock and Essex area."
  }
],
